enum EvidenceKind { terminal, remains, voxLog, ritualMark, witness }
class EvidenceDefinition { final String id,title,description; final EvidenceKind kind; final int clueValue; const EvidenceDefinition({required this.id,required this.title,required this.description,required this.kind,this.clueValue=1}); }
class InvestigationInteractionSystem { static const evidenceCatalog=<EvidenceDefinition>[
 EvidenceDefinition(id:'vox_fragment',title:'Фрагмент вокс-записи',description:'Повреждённая запись указывает на перемещение культистов.',kind:EvidenceKind.voxLog,clueValue:2),
 EvidenceDefinition(id:'ritual_trace',title:'След ритуала',description:'Остаточная энергия подтверждает присутствие варп-сущности.',kind:EvidenceKind.ritualMark,clueValue:2),
 EvidenceDefinition(id:'machine_log',title:'Журнал терминала',description:'Данные раскрывают скрытый маршрут снабжения.',kind:EvidenceKind.terminal,clueValue:3),
 EvidenceDefinition(id:'biological_sample',title:'Биологический образец',description:'Образец позволяет определить тип ксеноугрозы.',kind:EvidenceKind.remains,clueValue:1),
 EvidenceDefinition(id:'survivor_testimony',title:'Показания выжившего',description:'Свидетель может раскрыть имя связного.',kind:EvidenceKind.witness,clueValue:3),
 ]; final Set<String> collected=<String>{}; final Set<String> interrogated=<String>{}; int get clueScore=>collected.fold<int>(0,(sum,id)=>sum+(evidenceCatalog.where((e)=>e.id==id).firstOrNull?.clueValue??0)); bool collect(String id)=>evidenceCatalog.any((e)=>e.id==id)&&collected.add(id); bool interrogate(String id)=>evidenceCatalog.any((e)=>e.id==id&&e.kind==EvidenceKind.witness)&&interrogated.add(id); Map<String,dynamic> toJson()=>{'collected':collected.toList(),'interrogated':interrogated.toList()}; void loadJson(dynamic raw){if(raw is! Map)return;collected..clear()..addAll((raw['collected'] is List?raw['collected'] as List:const []).whereType<String>().where((id)=>evidenceCatalog.any((e)=>e.id==id)));interrogated..clear()..addAll((raw['interrogated'] is List?raw['interrogated'] as List:const []).whereType<String>().where((id)=>evidenceCatalog.any((e)=>e.id==id&&e.kind==EvidenceKind.witness)));} }
extension _EvidenceFirstOrNull<T> on Iterable<T>{T? get firstOrNull=>isEmpty?null:first;}
